<?phpclass Po extends MX_controller{    function __construct()    {        parent::__construct();        $this->load->model('D_Po');        $this->load->helper('url');        $this->load->helper('html');        $this->load->library('encryption');        $this->load->library('Pdf');        $this->load->helper('pdf_helper');    }    function penyebut($nilai) {		$nilai = abs($nilai);		$huruf = array("", "satu", "dua", "tiga", "empat", "lima", "enam", "tujuh", "delapan", "sembilan", "sepuluh", "sebelas");		$temp = "";		if ($nilai < 12) {			$temp = " ". $huruf[$nilai];		} else if ($nilai <20) {			$temp = $this->penyebut($nilai - 10). " belas";		} else if ($nilai < 100) {			$temp = $this->penyebut($nilai/10)." puluh". $this->penyebut($nilai % 10);		} else if ($nilai < 200) {			$temp = " seratus" . $this->penyebut($nilai - 100);		} else if ($nilai < 1000) {			$temp = $this->penyebut($nilai/100) . " ratus" . $this->penyebut($nilai % 100);		} else if ($nilai < 2000) {			$temp = " seribu" . $this->penyebut($nilai - 1000);		} else if ($nilai < 1000000) {			$temp = $this->penyebut($nilai/1000) . " ribu" . $this->penyebut($nilai % 1000);		} else if ($nilai < 1000000000) {			$temp = $this->penyebut($nilai/1000000) . " juta" . $this->penyebut($nilai % 1000000);		} else if ($nilai < 1000000000000) {			$temp = $this->penyebut($nilai/1000000000) . " milyar" . $this->penyebut(fmod($nilai,1000000000));		} else if ($nilai < 1000000000000000) {			$temp = $this->penyebut($nilai/1000000000000) . " trilyun" . $this->penyebut(fmod($nilai,1000000000000));		}     		return $temp;	}	function terbilang($nilai) {		if($nilai<0) {			$hasil = "minus ". trim($this->penyebut($nilai));		} else {			$hasil = trim($this->penyebut($nilai));		}     				return $hasil;	}    function tanggal_indo($tanggal, $cetak_hari = false)    {        $hari = array ( 1 =>    'Senin',                    'Selasa',                    'Rabu',                    'Kamis',                    'Jumat',                    'Sabtu',                    'Minggu'                );                        $bulan = array (1 =>   'Januari',                    'Februari',                    'Maret',                    'April',                    'Mei',                    'Juni',                    'Juli',                    'Agustus',                    'September',                    'Oktober',                    'November',                    'Desember'                );        $split 	  = explode('-', $tanggal);        $tgl_indo = $split[2] . ' ' . $bulan[ (int)$split[1] ] . ' ' . $split[0];                if ($cetak_hari) {            $num = date('N', strtotime($tanggal));            return $hari[$num] . ', ' . $tgl_indo;        }        return $tgl_indo;    }    function index(){        $datalist       = $this->D_Po->dlistpo();               $set_depo                    = @$this->session->userdata['sp']->set_depo;        $data = array(            'datalist'  => $datalist,            'set_depo'  => $set_depo        );        $this->load->view('list_po', $data);    }        function edit(){        $no_po      = $this->input->post('id_po');        $datasett   = $this->D_Po->dlistpo_edt($no_po);        $row_1      = $datasett->pbf;        $row_2      = $datasett->id_pbf;        $row_3      = $datasett->no_telp;        $row_4      = $datasett->tanggal;        $row_5      = $datasett->tanggal_fak;        $row_6      = $datasett->no_fak;        $row_7      = $datasett->no_surat_jalan;        $row_8      = $datasett->keterangan;        $data = array(            'no_po'     => $no_po,            'row_1'     => $row_1,            'row_2'     => $row_2,            'row_3'     => $row_3,            'row_4'     => $row_4,            'row_5'     => $row_5,            'row_6'     => $row_6,            'row_7'     => $row_7,            'row_8'     => $row_8        );		$dataset = json_encode($data);		echo $dataset;    }        function detailobat(){        $id_obat    = $this->input->post('id_obat');        $datasett   = $this->D_Po->detail_obatnya($id_obat);                $row_1      = $datasett->kemasan;        $row_2      = $datasett->satuan;        $row_3      = $datasett->konversi;        $data = array(            'row_1'     => $row_1,            'row_2'     => $row_2,            'row_3'     => $row_3        );		$dataset = json_encode($data);		echo $dataset;    }        function edit_tab(){        $no_po          = $this->input->post('id_po');        $data           = $this->D_Po->dlistpo_det_edt($no_po);		$dataset = json_encode($data);		echo $dataset;    }        public function mstbahan(){		$term = $this->input->get('term',true);				$sql = "SELECT 	a.id_fa AS id_obat,a.name AS nama_obat						FROM 		mst_farmalkes a 						WHERE 	UPPER(a.name) LIKE '%".strtoupper($term)."%'						";		$query  = $this->db->query($sql);		$rs     = $query->result_array();		foreach($rs as $k => $v)		{			$rs[$k]['label'] = $v['nama_obat'];			$rs[$k]['id'] = $v['id_obat'];		}		$dataset = json_encode($rs);		echo $dataset;    }    public function mstsupplier(){		$term = $this->input->get('term',true);				$sql = "SELECT a.id_sup AS id_supplier,a.name AS nama_supplier,a.telp AS no_telp						FROM mst_supplier a 						WHERE UPPER(a.name) LIKE '%".strtoupper($term)."%'						";		$query  = $this->db->query($sql);		$rs     = $query->result_array();		foreach($rs as $k => $v)		{			$rs[$k]['label'] = $v['nama_supplier'];			$rs[$k]['id'] = $v['id_supplier'];            $rs[$k]['no_telp'] = $v['no_telp'];		}		$dataset = json_encode($rs);		echo $dataset;    }    function escape($text){       return str_replace(array(","), array(""), $text);    }    function save(){        $username                      = @$this->session->userdata['sp']->login_name;                $set_depo                    = @$this->session->userdata['sp']->set_depo;        $id_supplier_set               = $this->input->post('id_supplier');        $suppliersearch_set            = $this->input->post('suppliersearch');        $tgl_order_set                 = $this->input->post('tgl_order');        $id_obat_set                   = $this->input->post('id_obat');        $nama_obat_set                 = $this->input->post('nama_obat');         $no_telp_set                   = $this->input->post('no_telp');        $tgl_faktur_set                = $this->input->post('tgl_faktur');        $no_fak_set                    = $this->input->post('no_fak');        $no_sujan_set                  = $this->input->post('no_sujan');        $kemasan_set                   = $this->input->post('kemasan');        $qtyr_set                      = $this->input->post('qtyr');        $satuan_set                    = $this->input->post('satuan');        $jumlah_bahan_set              = $this->input->post('jumlah_order');        $keterangan_set                = $this->input->post('keterangan');        $datetime                      = date('Y-m-d H:i:s');        //gen no po        $checkid                       = $this->D_Po->cdk();        $setnoreg                      = $checkid->no_po;        $prefix       = "PO-";        $datereal_tgl = date('d');        $datereal_bln = date('m');        $datereal_thn = date('y');        $setidregfnc = $setnoreg;        $setnoreg_bln = substr($setidregfnc, 5, 2);        $setnoreg_thn = substr($setidregfnc, 7, 2);        $urutan_reg = (int) substr($setidregfnc, 12, 17);        //echo $datereal_bln.$datereal_thn.$idcabang.sprintf("%05s", $setincrement_reg)."<br>";        if(($datereal_bln==$setnoreg_bln) && ($datereal_thn==$setnoreg_thn)){            $setincrement_reg = $urutan_reg+1;            $id_poset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn."FA".sprintf("%06s", $setincrement_reg);        }elseif(($datereal_bln!=$setnoreg_bln) && ($datereal_thn==$setnoreg_thn)){ //tahun berjalan             $setincrement_reg = "000001";            $id_poset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn."FA".$setincrement_reg;        }elseif(($datereal_bln!=$setnoreg_bln && $datereal_thn!=$setnoreg_thn)){ //tahun selanjutnya (awal tahun)            $setincrement_reg = "000001";            $id_poset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn."FA".$setincrement_reg;        }else{            $setincrement_reg = "000001";            $id_poset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn."FA".$setincrement_reg;        }        //end gen no po            $datains = array(                  'no_po'             =>   $id_poset,                'id_pbf'            =>   $id_supplier_set,                'pbf'               =>   $suppliersearch_set,                'no_telp'          =>   $no_telp_set,                'tanggal'           =>   $tgl_order_set,                'tanggal_fak'       =>   $tgl_faktur_set,                'no_fak'            =>   $no_fak_set,                'no_surat_jalan'    =>   $no_sujan_set,                'keterangan'        =>   $keterangan_set,                'created'           =>   $datetime,                'created_by'        =>   $username                    );            $this->D_Po->ins1($datains,'ish_wioutpo');         	### ----------- //KARTU STOK ----------------------------------------------			$datetime = date('Y-m-d H:i:s');			//gen no sto        	$checkid                       = $this->D_Po->cdk_kartu_stok();        	$setnoreg                      = $checkid->id_kode;        	$prefix       = "PTO-";        	$datereal_tgl = date('d');        	$datereal_bln = date('m');        	$datereal_thn = date('y');        	$setidregfnc = $setnoreg;        	$setnoreg_bln = substr($setidregfnc, 6, 2);        	$setnoreg_thn = substr($setidregfnc, 8, 2);        	$urutan_reg = (int) substr($setidregfnc, 10, 16);        	//echo $datereal_bln.$datereal_thn.$idcabang.sprintf("%05s", $setincrement_reg)."<br>";        	if(($datereal_bln==$setnoreg_bln) && ($datereal_thn==$setnoreg_thn)){        	    $setincrement_reg = $urutan_reg+1;        	    $id_stoset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn.sprintf("%06s", $setincrement_reg);        	}elseif(($datereal_bln!=$setnoreg_bln) && ($datereal_thn==$setnoreg_thn)){ //tahun berjalan         	    $setincrement_reg = "000001";        	    $id_stoset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn.$setincrement_reg;        	}elseif(($datereal_bln!=$setnoreg_bln && $datereal_thn!=$setnoreg_thn)){ //tahun selanjutnya (awal tahun)        	    $setincrement_reg = "000001";        	    $id_stoset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn.$setincrement_reg;        	}else{        	    $setincrement_reg = "000001";        	    $id_stoset = $prefix.$datereal_tgl.$datereal_bln.$datereal_thn.$setincrement_reg;        	}        	//end gen no sto            //STO            ///////////////////////////////////////////////////////////////////////kartu stok STO        foreach($id_obat_set as $k => $v){            $id_obat      = $id_obat_set[$k];            $nama_obat    = $nama_obat_set[$k];            $kemasan      = $kemasan_set[$k];            $qtyr         = $qtyr_set[$k];            $satuan       = $satuan_set[$k];             $jumlah_bahan = $jumlah_bahan_set[$k];            $datains = array(                  'no_po'             =>   $id_poset,                'id_obat'           =>   $id_obat,                'nama_obat'         =>   $nama_obat,                'kemasan'           =>   $kemasan,                'qtyr'              =>   $this->escape($qtyr),                'satuan'            =>   $satuan,                'jumlah_order'      =>   $this->escape($jumlah_bahan),                'created'           =>   $datetime,                'created_by'        =>   $username            );            $this->D_Po->ins1($datains,'ish_wioutpo_det');                         $qty_depot 		= ($depot_check->qty + $this->escape($qtyr));							            $gdu_datains2 = array(                  'id_wrh'         =>   $set_depo,                'id_fa'          =>   $id_obat,                'datetime'       =>   $datetime,                'id_kode'        =>   $id_stoset,                'kode'           =>   'PTO',                'nama_transaksi' =>   $id_stoset.'/ '.$nama_obat.' / 0 / 0 / 90 / '.$username.' / '.$datetime,                'in'            =>   $this->escape($qtyr),                'saldo'          =>   $qty_depot,                'created'        =>   $datetime,                'created_by'     =>   $this->session->userdata['sp']->login_name            );            $this->D_Po->ins1($gdu_datains2,'gdf_kartu_stok');			$dataupd = array(                  'qty'       	=>   $qty_depot,            );            $dataupd_where = array(				'id_wrh'         =>   $set_depo,                'id_soh'         =>   $id_obat,            );            $this->D_Po->update_data($dataupd_where,$dataupd,'mst_soh');        }        						///////////////////LOG SYSTEM			$infoset     = "Penerimaan tanpa PO ".$this->session->userdata['sp']->login_name.' -> '.date('Y-m-d H:i:s');			$data_log = array(				'type' 	        =>	"90",				'attempt_1'     =>	base_url(),				'attempt_2'	    => 	"Pembayaran / ".$new_id_inv,				'info' 	        =>	$infoset,				'created'		=>  date('Y-m-d H:i:s'),				'created_by'	=>  $this->session->userdata['sp']->login_name			);			$this->D_Po->add_to_log($data_log);			///////////////////LOG SYSTEM			            ////////////////////////////////////////////////////////////////////////End kartu stok        redirect('wioutpo/po');        }    function editthis(){        $username                      = @$this->session->userdata['sp']->username;        $id_company                    = @$this->session->userdata['sp']->id_company;        $no_po_set                     = $this->input->post('no_po');        $id_supplier_set               = $this->input->post('id_supplier');        $tgl_order_set                 = $this->input->post('tgl_order');        //$id_obat_set                  = $this->input->post('id_obat');        //$nama_obat_set                = $this->input->post('nama_obat');        //$jumlah_bahan_set              = $this->input->post('jumlah_order');        $alamat_pengiriman_set         = $this->input->post('alamat_pengiriman');        $keterangan_set                = $this->input->post('keterangan');        $datetime                      = date('Y-m-d H:i:s');            $dataupd = array(                  'id_supplier'       =>   $id_supplier_set,                'tgl_po'            =>   $tgl_order_set,                'alamat_pengiriman' =>   $alamat_pengiriman_set,                'keterangan'        =>   $keterangan_set,                'updated'           =>   $datetime,                'updated_by'        =>   $username                    );            $dataupd_where = array(                'no_po'             => $no_po_set            );            $this->D_Po->update_data($dataupd_where,$dataupd,'trx_createmstpo');            //ins bahan            /*foreach($nama_obat_set as $k => $v){                $id_obat      = $id_obat_set[$k];                $nama_obat    = $nama_obat_set[$k];                $jumlah_bahan  = $jumlah_bahan_set[$k];                    $datains = array(                      'no_po'             =>   $no_po_set,                    'id_obat'          =>   $id_obat,                    'nama_obat'        =>   $nama_obat,                    'jumlah'            =>   $this->escape($jumlah_bahan),                    'id_company'        =>   $id_company,                    'created'           =>   $datetime,                    'created_by'        =>   $username                                );                $this->D_Po->ins1($datains,'trx_createpo');             }*/        redirect('po/');        }    function deleteitemedit(){        $id_set = $this->input->post('id_item');        $sql = "UPDATE ish_wioutpo_det SET status = '1',updated='$datetime',updated_by='$username' WHERE id='$id_set'";        $this->db->query($sql);        $data="ok";        $dataset = json_encode($data);		echo $dataset;    }    function deleteitempo(){        $username   = @$this->session->userdata['sp']->username;        $datetime   = date('Y-m-d H:i:s');        $no_po      = $this->input->post('id_po');        $sql        = "UPDATE ish_wioutpo SET status = '1',updated='$datetime',updated_by='$username' WHERE no_po='$no_po'; ";        $this->db->query($sql);        $data="ok";        $dataset = json_encode($data);		echo $dataset;    }        function cetakpo($no_po){                $datalist               = $this->D_Po->dlistpo_set($no_po);        $datanya                = $this->D_Po->dlistpo_nya($no_po);        $datanya_pembayaran     = $this->D_Po->dlistpo_pembayaran($no_po);                $row_1_a            =   $datanya->nama_supplier;        $row_1_b            =   $datanya->alamat;        $row_1_c            =   $datanya->keterangan;        $row_3              =   $datanya->no_po;        $row_4              =   $datanya->nama_pengirim;        $id_customer        =   $datanya->id_supplier;        $tgl_pj             =   $this->tanggal_indo($datanya->tgl_po);         $tgl_do             =   $this->tanggal_indo($datanya->tgl_do);        $tgl_jatuh_tempo    =   $this->tanggal_indo($datanya->tgl_jth_tempo);         $no_do              =   $datanya->no_po;        $id_pengirim        =   $datanya->id_pengirim;        $syarat_pembayaran  =   $datanya->syarat_pembayaran;         $no_po_cust         =   $datanya->no_po_cust;        $driver             =   $datanya->driver;          $mengetahui_atasan  =   $datanya->mengetahui_atasan;        $alamat_pengiriman  =   $datanya->alamat_pengiriman;        $keterangan         =   $datanya->keterangan;        $created_by         =   $datanya->created_by;        $data = array(            'datalist'              => $datalist,            'datanya_pembayaran'    => $datanya_pembayaran,            'row_1_a'               => $row_1_a,            'row_1_b'               => $row_1_b,            'row_1_c'               => $row_1_c,            'row_3'                 => $row_3,            'row_4'                 => $row_4,            'id_customer'           => $id_customer,            'tgl_pj'                => $tgl_pj,            'tgl_do'                => $tgl_do,            'tgl_jatuh_tempo'       => $tgl_jatuh_tempo,            'no_do'                 => $no_do,            'id_pengirim'           => $id_pengirim,            'syarat_pembayaran'     => $syarat_pembayaran,            'no_pj'                 => $no_po,            'no_po_cust'            => $no_po_cust,            'driver'                => $driver,            'mengetahui_atasan'     => $mengetahui_atasan,            'alamat_pengiriman'     => $alamat_pengiriman,            'keterangan'            => $keterangan,            'created_by'            => $created_by        );        $this->load->view('cetakpo', $data);    }}?>